  "jsonrpc": "2.0",
  "id": 12,
  "result": {
    "content": [
      {
        "type": "text",
        "text": "{\n  \"status\": \"AST_LINT_VIOLATION\",\n  \"success\": false,\n  \"error\": \"Line 1: Prohibited import 'subprocess'\",\n  \"violations\": [\n    \"Line 1: Prohibited import 'subprocess'\"\n  ],\n  \"active_beliefs\": \"No verified facts recorded.\",\n  \"stdout\": \"\",\n  \"errors\": [\n    \"Line 1: Prohibited import 'subprocess'\"\n  ]\n}"
      }
