### 3.3 `memory_evolve`

Semantic memory management, Open Knowledge Format (OKF) indexing, AGM Levi belief revision, epistemic garbage collection, and cross-project global invariant distillation.

#### JSON Schema
```json
{
  "name": "memory_evolve",
  "description": "Semantic memory: AGM revision, GC, distill_global, query_global, search, persist.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "enum": [
          "search",
          "persist",
          "evolve",
          "gc",
          "revise",
          "distill_global",
          "query_global"
        ],
        "default": "search",
        "description": "Memory evolution action."
      },
      "query": {
        "type": "string",
        "description": "Search term or concept query."
      },
      "title": {
        "type": "string",
        "description": "Document title for persist, revise, or distillation."
      },
      "content": {
        "type": "string",
        "description": "Markdown body content to persist or revise."
      },
      "code": {
        "type": "string",
        "description": "Source code snippet for cross-project global distillation."
      },
      "repo_path": {
        "type": "string",
        "description": "Optional repository path for salted HMAC isolation."
      },
      "tags": {
        "type": "array",
        "items": { "type": "string" },
        "description": "Tags associated with the knowledge entity."
      },
      "entity_type": {
        "type": "string",
        "default": "concept",
        "description": "OKF entity type ('concept', 'adr', 'spec', 'task', 'log')."
      },
      "linked_symbols": {
        "type": "array",
