  "jsonrpc": "2.0",
  "id": 13,
  "method": "tools/call",
  "params": {
    "name": "memory_evolve",
    "arguments": {
      "action": "revise",
      "title": "ADR-051 Swarm OCC Concurrency",
      "content": "Adopt Kung-Robinson OCC for parallel agent worktrees.",
      "supersedes": ["ADR-002 Pessimistic Mutex"]
