        "type": "text",
        "text": "{\n  \"status\": \"REVISED\",\n  \"contracted\": [\n    \"ADR-002 Pessimistic Mutex\"\n  ],\n  \"title\": \"ADR-051 Swarm OCC Concurrency\"\n}"
